// Create a new compiler handle and ensure it is valid
shaderc_compiler_t handle = shaderc_compiler_initialize();
if (!handle) { FUZZ_BAIL(); }
// Allocate a cell to store the opaque handle for the fuzzer pool (type is shaderc_compiler_t*)
shaderc_compiler_t *compiler = new shaderc_compiler_t;
*compiler = handle;
// Track liveness for later release and API constraints
FUZZ_SET_ATTR_STR(compiler, "type", "compiler");
FUZZ_SET_ATTR_INT(compiler, "valid", 1);
// Validation: non-null handle stored in a persistent cell; attributes set for lifecycle management.

// Validate input handle came from initialize and is not already released
if (!compiler) { FUZZ_BAIL(); }
int valid = FUZZ_GET_ATTR_INT(compiler, "valid");
if (!valid) { FUZZ_BAIL(); }
if (!*compiler) { FUZZ_BAIL(); }
// Release the compiler; after this, it must not be used again
shaderc_compiler_release(*compiler);
// Mark as invalid and clear the stored handle to prevent reuse
*compiler = nullptr;
FUZZ_SET_ATTR_INT(compiler, "valid", 0);
// Validation: handle released exactly once; cell retained but marked invalid to avoid reuse.

// Create a new compile options object
shaderc_compile_options_t handle = shaderc_compile_options_initialize();
if (!handle) { FUZZ_BAIL(); }
// Store in a persistent cell for the fuzzer pool
shaderc_compile_options_t *options = new shaderc_compile_options_t;
*options = handle;
// Track liveness and type
FUZZ_SET_ATTR_STR(options, "type", "options");
FUZZ_SET_ATTR_INT(options, "valid", 1);
// Validation: non-null options handle stored and marked valid for subsequent setters.

// Optionally exercise NULL-in, or clone the provided options
if (!options) { FUZZ_BAIL(); }
shaderc_compile_options_t src = nullptr;
int use_null = (int)(*FUZZ_PARAM(unsigned int) % 2);
if (!use_null) {
  if (!FUZZ_GET_ATTR_INT(options, "valid")) { FUZZ_BAIL(); }
  if (!*options) { FUZZ_BAIL(); }
  src = *options;
}
shaderc_compile_options_t clone_handle = shaderc_compile_options_clone(src);
if (!clone_handle) { FUZZ_BAIL(); }
// Wrap the clone handle in a new cell for the pool
shaderc_compile_options_t *options_clone = new shaderc_compile_options_t;
*options_clone = clone_handle;
FUZZ_SET_ATTR_STR(options_clone, "type", "options");
FUZZ_SET_ATTR_INT(options_clone, "valid", 1);
// Validation: clone succeeds for both NULL and valid source; both original and clone are returned to remain live.

// Release an options object; API allows NULL, but fuzzer runtime guarantees non-null inputs
if (!options) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(options, "valid")) { FUZZ_BAIL(); }
if (!*options) { FUZZ_BAIL(); }
shaderc_compile_options_release(*options);
*options = nullptr;
FUZZ_SET_ATTR_INT(options, "valid", 0);
// Validation: options released exactly once; cell marked invalid to prevent further use.

// Ensure options is valid and we have a live handle
if (!options || !FUZZ_GET_ATTR_INT(options, "valid") || !*options) { FUZZ_BAIL(); }
// Generate macro name/value according to contract
std::string name = FUZZ_PARAM_STR();
size_t name_length = name.size();
if (name_length == 0) { FUZZ_BAIL(); }
// Randomly choose valueless or valued macro
int use_value = (int)(*FUZZ_PARAM(unsigned int) % 2);
if (use_value) {
  std::string value = FUZZ_PARAM_STR();
  const char* value_ptr = value.empty() ? nullptr : value.c_str();
  size_t value_length = value.empty() ? 0u : value.size();
  // Perform the call while the strings are alive
  shaderc_compile_options_add_macro_definition(*options, name.c_str(), name_length, value_ptr, value_length);
} else {
  // Explicitly add valueless macro; API allows value_ptr NULL or value_length 0
  shaderc_compile_options_add_macro_definition(*options, name.c_str(), name_length, nullptr, 0u);
}
// Validation: strings remain valid during calls; options remains live and returned to pool.

if (!options || !FUZZ_GET_ATTR_INT(options, "valid") || !*options) { FUZZ_BAIL(); }
// Generate a valid shaderc_source_language enum (0..1)
unsigned int lang_val = *FUZZ_PARAM(unsigned int) % 2;
shaderc_source_language lang = (shaderc_source_language)lang_val;
shaderc_compile_options_set_source_language(*options, lang);
// Validation: setter invoked on a valid options handle, options returned to remain live.

if (!options || !FUZZ_GET_ATTR_INT(options, "valid") || !*options) { FUZZ_BAIL(); }
shaderc_compile_options_set_generate_debug_info(*options);
// Validation: toggles debug info on a valid options object; options returned.

if (!options || !FUZZ_GET_ATTR_INT(options, "valid") || !*options) { FUZZ_BAIL(); }
// Valid optimization levels are 0..2
unsigned int lvl_val = *FUZZ_PARAM(unsigned int) % 3;
shaderc_optimization_level lvl = (shaderc_optimization_level)lvl_val;
shaderc_compile_options_set_optimization_level(*options, lvl);
// Validation: optimization level set within enum range; options returned.

if (!options || !FUZZ_GET_ATTR_INT(options, "valid") || !*options) { FUZZ_BAIL(); }
// Generate a GLSL version resembling typical #version values (100..460)
unsigned int v = *FUZZ_PARAM(unsigned int) % 361 + 100; // 100..460
v = (v / 10) * 10; // round to multiple of 10
int version = (int)v;
// Choose profile: versions < 150 require shaderc_profile_none
shaderc_profile prof;
if (version < 150) {
  prof = shaderc_profile_none;
} else {
  unsigned int pick = *FUZZ_PARAM(unsigned int) % 2;
  prof = pick ? shaderc_profile_core : shaderc_profile_es;
}
