    + INFER_PRAGMA_SHADERS
    + PP_SNIPPETS
)

IDENT_FIRST = string.ascii_letters + "_"
IDENT_REST = IDENT_FIRST + string.digits


def rand_ident(rng: random.Random, min_len: int = 1, max_len: int = 16) -> str:
    n = rng.randint(min_len, max_len)
    s = rng.choice(IDENT_FIRST)
    if n > 1:
        s += ''.join(rng.choice(IDENT_REST) for _ in range(n - 1))
    return s


def rand_filename(rng: random.Random) -> str:
    base = rand_ident(rng, 3, 10)
    ext = rng.choice([".glsl", ".vert", ".frag", ".comp", ".geom", ".tesc", ".tese"])    
    return base + ext


def lp_string(data: bytes) -> bytes:
    # length-prefixed (uint32 little endian) + payload
    ln = len(data)
    return ln.to_bytes(4, 'little') + data


def pack_uint32(v: int) -> bytes:
    return (v & 0xFFFFFFFF).to_bytes(4, 'little')


def build_shader_with_macros(rng: random.Random) -> str:
    # Randomly wrap a base shader with some macro uses
    src = rng.choice(ALL_SOURCES)
    # Add some macro definitions at top to interact with AddMacroDefinition calls
    macros = []
    for _ in range(rng.randint(0, 3)):
        name = rand_ident(rng)
        if rng.random() < 0.5:
            macros.append(f"#define {name}\n")  # valueless
        else:
            val = rng.choice(["1", "2", "0", "(1+2)", "3.14"])
            macros.append(f"#define {name} {val}\n")
    header = "#version 450\n" if not src.startswith("#version") else ""
    return header + "".join(macros) + src


def assemble_string_pool(rng: random.Random) -> List[str]:
    pool: List[str] = []
    # Provide several identifiers for macro names and entry points
    for _ in range(6):
        pool.append(rand_ident(rng))
    # Macro values: numbers and small tokens
    for _ in range(4):
        pool.append(rng.choice(["1", "0", "42", "3.1415", "TEXT", "VALUE"]))
    # Entry point names: include "main" and alternates
    pool.append("main")
    pool.append(rand_ident(rng))
    # File names for diagnostics
    for _ in range(3):
        pool.append(rand_filename(rng))
    # Several shader sources (some with pragma, some different stages)
    for _ in range(4):
        pool.append(build_shader_with_macros(rng))
    # Additional short sources to keep variety and size constraints
    pool.append("#version 450\nvoid main(){}")
    pool.append("#version 310 es\nprecision mediump float; void main(){}")
    return pool


def assemble_int_pool(rng: random.Random) -> List[int]:
    ints: List[int] = []
    # Toggle bits for options being null/non-null and valued/valueless macros
    for _ in range(16):
        ints.append(rng.getrandbits(32))
    return ints


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    strings = assemble_string_pool(rng)
    ints = assemble_int_pool(rng)

    # Encode: [num_strings][strings...][num_ints][ints...]
    out = bytearray()
    out += pack_uint32(len(strings))
    for s in strings:
        b = s.encode('utf-8')
        # Truncate overly long shader to keep total under limit
        if len(b) > 1536:
            b = b[:1536]
        out += lp_string(b)
    out += pack_uint32(len(ints))
    for v in ints:
        out += pack_uint32(v)

    # Ensure size <= MAX_TOTAL; if exceeding, drop trailing content conservatively
    if len(out) > MAX_TOTAL:
        # Trim by removing some trailing ints first
        # Keep structure valid: adjust num_ints accordingly
        # Rebuild ints section with fewer entries
        # Find where ints section starts
        idx = 0
        num_str = int.from_bytes(out[idx:idx+4], 'little'); idx += 4
        # Skip strings
        for _ in range(num_str):
            if idx + 4 > len(out):
                break
            l = int.from_bytes(out[idx:idx+4], 'little'); idx += 4 + l
        # idx now at num_ints
        if idx + 4 <= len(out):
            # Rebuild from start up to ints header
            head = out[:idx]
            remaining = MAX_TOTAL - (idx + 4)
            per = 4
            max_ints = max(0, remaining // per)
            trimmed = ints[:max_ints]
            new = bytearray()
            new += pack_uint32(len(trimmed))
            for v in trimmed:
                new += pack_uint32(v)
            out = head + new
        # If still too big, as last resort slice
        if len(out) > MAX_TOTAL:
            out = out[:MAX_TOTAL]

    return bytes(out)

import random
import string
from typing import List

# This generator produces valid shader source strings and filename-like tags
# to exercise shaderc compilation and preprocessing paths in the fuzzers.
# The fuzzer will request multiple FUZZ_PARAM_STR() values from a single
# input buffer; we therefore encode a sequence of null-terminated strings.
# Order:
#  - One or more GLSL/HLSL shader sources covering different stages/features
#  - Several short filename-like tags (used for input_file_name and entry point)
#  - A pair of include name/content blobs for the includer stub
# The consumer splits by '\0' in order. We ensure each token is short enough
# to meet the stub truncation limits, and all are valid ASCII/UTF-8.

MAX_TOTAL = 4096

GLSL_HEADERS = [
    "#version 450 core\n",
    "#version 310 es\nprecision highp float;\n",
    "#version 460 core\n",
]

# Minimal valid shaders for different stages
VERT_GLSL = """
#version 450 core
layout(location=0) in vec3 in_pos;
layout(location=1) in vec2 in_uv;
layout(location=0) out vec2 v_uv;
void main(){ v_uv = in_uv; gl_Position = vec4(in_pos, 1.0); }
""".strip()+"\n"

FRAG_GLSL = """
#version 450 core
layout(location=0) in vec2 v_uv;
layout(location=0) out vec4 out_color;
layout(binding=0) uniform sampler2D tex0;
void main(){ out_color = texture(tex0, v_uv); }
""".strip()+"\n"

COMP_GLSL = """
#version 450 core
layout(local_size_x=8, local_size_y=8) in;
layout(rgba8, binding=0) uniform writeonly image2D img;
void main(){ ivec2 c = ivec2(gl_GlobalInvocationID.xy); imageStore(img, c, vec4(1.0)); }
""".strip()+"\n"

GEOM_GLSL = """
#version 450 core
layout(triangles) in;
layout(triangle_strip, max_vertices=3) out;
layout(location=0) out vec3 g_n;
void main(){
  for(int i=0;i<3;i++){ gl_Position = gl_in[i].gl_Position; EmitVertex(); }
  EndPrimitive();
}
""".strip()+"\n"

TESC_GLSL = """
#version 450 core
layout(vertices = 3) out;
void main(){
  if (gl_InvocationID == 0) {
    gl_TessLevelOuter[0]=1; gl_TessLevelOuter[1]=1; gl_TessLevelOuter[2]=1;
    gl_TessLevelInner[0]=1;
  }
  gl_out[gl_InvocationID].gl_Position = gl_in[gl_InvocationID].gl_Position;
}
""".strip()+"\n"

TESE_GLSL = """
#version 450 core
layout(triangles, equal_spacing, cw) in;
void main(){ gl_Position = (gl_TessCoord.x*gl_in[0].gl_Position + gl_TessCoord.y*gl_in[1].gl_Position + gl_TessCoord.z*gl_in[2].gl_Position); }
""".strip()+"\n"

# Valid HLSL pixel/vertex shaders with entry points
HLSL_VS = """
float4 main(float3 pos : POSITION) : SV_Position { return float4(pos, 1.0); }
""".strip()+"\n"

HLSL_PS = """
Texture2D tex0 : register(t0);
SamplerState samp0 : register(s0);
float4 main(float2 uv : TEXCOORD0) : SV_Target { return tex0.Sample(samp0, uv); }
""".strip()+"\n"

# A pragma-based inference token to exercise shaderc_glsl_infer_from_source
PRAGMA_VERTEX = "#pragma shader_stage(vertex)\nvoid main(){}\n"
PRAGMA_FRAGMENT = "#pragma shader_stage(fragment)\nlayout(location=0) out vec4 c; void main(){ c=vec4(0); }\n"

# Include-driven shader to exercise includer callbacks
INCLUDE_USER = """
#version 450 core
#include "inc.glsl"
void main(){ main_inc(); }
""".strip()+"\n"

INCLUDE_CONTENT = """
#version 450 core
void main_inc() {}
""".strip()+"\n"

# SPIR-V assembly snippet (valid starter) to feed Assemble paths when used
SPV_ASM_MIN = """; SPIR-V\n; Version: 1.0\n; Generator: 0\n; Bound: 4\n; Schema: 0\n               OpCapability Shader\n          %1 = OpExtInstImport "GLSL.std.450"\n               OpMemoryModel Logical GLSL450\n               OpEntryPoint Vertex %2 "main"\n       %void = OpTypeVoid\n          %3 = OpTypeFunction %void\n          %2 = OpFunction %void None %3\n               OpReturn\n               OpFunctionEnd\n""".strip()+"\n"

FILENAME_TOKENS = ["shader.vert", "shader.frag", "input.glsl", "hlsl.hlsl", "file.tag"]
ENTRYPOINT_TOKENS = ["main", "VSMain", "PSMain", "ComputeMain"]


def _rand_choice(r: random.Random, seq: List[str]) -> str:
    return seq[r.randrange(len(seq))]


def _make_filename(r: random.Random) -> str:
    base = _rand_choice(r, FILENAME_TOKENS)
    # Occasionally randomize
    if r.random() < 0.5:
        extra = ''.join(r.choice(string.ascii_letters+string.digits) for _ in range(r.randint(0,6)))
        if extra:
            base = extra + "_" + base
    return base[:64]


def _make_entry(r: random.Random) -> str:
    s = _rand_choice(r, ENTRYPOINT_TOKENS)
    if r.random() < 0.3:
        s = s + str(r.randint(0,9))
    return s[:32]


def _make_shader_set(r: random.Random) -> List[str]:
    shaders = []
    # Always include at least one valid GLSL shader
    shaders.append(_rand_choice(r, [VERT_GLSL, FRAG_GLSL, COMP_GLSL]))
    # Optionally add more to populate further FUZZ_PARAM_STR() calls
    pool = [GEOM_GLSL, TESC_GLSL, TESE_GLSL, INCLUDE_USER, PRAGMA_VERTEX, PRAGMA_FRAGMENT]
    if r.random() < 0.8:
        shaders.append(_rand_choice(r, [FRAG_GLSL, VERT_GLSL, COMP_GLSL]))
    for _ in range(r.randint(0, 3)):
        shaders.append(_rand_choice(r, pool))
    # Occasionally add HLSL sources
    if r.random() < 0.5:
        shaders.append(_rand_choice(r, [HLSL_VS, HLSL_PS]))
    # Occasionally add SPIR-V assembly to hit assemble paths if used
    if r.random() < 0.3:
        shaders.append(SPV_ASM_MIN)
    # Truncate each to the fuzzer cap (1536)
    shaders = [s[:1536] for s in shaders]
    return shaders


def _encode_null_terminated(tokens: List[str]) -> bytes:
    out = bytearray()
    for t in tokens:
        b = t.encode('utf-8', errors='strict')
        out += b + b"\x00"
        if len(out) >= MAX_TOTAL:
            break
    return bytes(out[:MAX_TOTAL])


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    tokens: List[str] = []

    # 1) Shader sources (multiple to satisfy repeated FUZZ_PARAM_STR calls)
    tokens.extend(_make_shader_set(r))

    # 2) A handful of filename-like tags
    for _ in range(3):
        tokens.append(_make_filename(r))

    # 3) Entry point names (multiple; fuzzers cap to 32 and default to "main")
    for _ in range(3):
        tokens.append(_make_entry(r))

    # 4) Include name/content for the includer stub
    tokens.append("inc.glsl")
    tokens.append(INCLUDE_CONTENT)

    # 5) Extra short tokens to pad variety (macros, version/profile strings)
    extra = ["DEFINE_FOO", "450core", "310es", "es", "core", "compatibility"]
    r.shuffle(extra)
    tokens.extend(extra[:r.randint(2, 6)])

    # Ensure we have at least a few tokens
    if not tokens:
        tokens = [VERT_GLSL, "shader.glsl", "main", "inc.glsl", INCLUDE_CONTENT]

    return _encode_null_terminated(tokens)

import random
from typing import List

# Generator for GLSL version/profile tokens used by shaderc_parse_version_profile.
# Requirement from harness: produce many unique outputs across runs with different seeds.
# We keep tokens valid most of the time while introducing varied, but still valid, spellings
# and constructions. We ensure size <= 64 bytes.

_DESKTOP_VERSIONS = [110, 120, 130, 140, 150, 330, 400, 410, 420, 430, 440, 450, 460]
_ES_VERSIONS = [100, 300, 310, 320]

def _valid_bases() -> List[str]:
    tokens: List[str] = []
    # Version only
    for v in _DESKTOP_VERSIONS:
        tokens.append(str(v))
    # Desktop with profiles
    for v in _DESKTOP_VERSIONS:
        tokens.append(f"{v}core")
        if v >= 150:
            tokens.append(f"{v}compatibility")
    # ES
    for v in _ES_VERSIONS:
        tokens.append(f"{v}es")
    # Dedup preserve order
    seen = set()
    out = []
    for t in tokens:
        if t not in seen:
            seen.add(t)
            out.append(t)
    return out

_BASES = _valid_bases()

def _rand_case(rng: random.Random, s: str) -> str:
    # Randomize case per character to diversify (mostly keep lower for validity)
    if rng.random() < 0.75:
        return s  # keep canonical
    # mix: lower/capitalize/upper patterns
    mode = rng.random()
    if mode < 0.5:
        return s.capitalize()
    elif mode < 0.8:
        return s.upper()
    else:
        return ''.join(ch.upper() if rng.random() < 0.3 else ch.lower() for ch in s)

def _emit_valid(rng: random.Random) -> str:
    # Choose strategy to diversify outputs
    strat = rng.random()
    if strat < 0.4:
        base = rng.choice(_BASES)
        # Split into version and profile suffix
        i = 0
        while i < len(base) and base[i].isdigit():
            i += 1
        ver = base[:i]
        prof = base[i:]
        # Optionally tweak version slightly within reasonable set
        if rng.random() < 0.2:
            # pick from nearby known versions to add variety
            if prof == 'es':
                ver = str(rng.choice(_ES_VERSIONS))
            else:
                ver = str(rng.choice(_DESKTOP_VERSIONS))
        # Randomize profile case a bit
        prof = _rand_case(rng, prof) if prof else prof
        token = ver + prof
        return token
    elif strat < 0.7:
        # Build from components for more combinations
        if rng.random() < 0.35:
            # ES token
            ver = str(rng.choice(_ES_VERSIONS))
            prof = 'es'
        else:
            ver = str(rng.choice(_DESKTOP_VERSIONS))
            prof_choice = rng.random()
            if prof_choice < 0.4:
                prof = ''
            elif prof_choice < 0.7:
                prof = 'core'
            else:
                # Only valid for >=150; if lower chosen, switch to a valid one
                if int(ver) < 150:
                    prof = 'core'
                else:
                    prof = 'compatibility'
        token = ver + _rand_case(rng, prof)
        return token
    else:
        # Sprinkle in optional preceding/trailing whitespace (rare) but keep most valid
        base = rng.choice(_BASES)
        # Mostly no spaces; sometimes add one space around to diversify while often still parseable
        if rng.random() < 0.15:
            ws_left = '' if rng.random() < 0.5 else ' '
            ws_right = '' if rng.random() < 0.5 else ' '
            return f"{ws_left}{base}{ws_right}"
        return base

def _emit_invalid(rng: random.Random) -> str:
    # A variety of invalid forms to exercise failure paths
    choices = []
    # Non-numeric
    choices += ['abc', 'core', 'es', 'compatibility']
    # Unsupported versions / mismatched profiles
    choices += ['999', '450escore', '310compatibility', '150es', '0450core']
    # Spaces and punctuation
    choices += ['450 core', '310 es', '450\tcore', '450-core']
    # Empty or too long
    choices += ['', '0', '1']
    pick = rng.choice(choices)
    # Occasionally random noise to increase diversity
    if rng.random() < 0.2:
        alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789_ -\t'
        n = rng.randint(1, 10)
        pick = ''.join(rng.choice(alphabet) for _ in range(n))
    return pick

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Mix valid vs invalid with strong bias to valid
    if rng.random() < 0.9:
        token = _emit_valid(rng)
    else:
        token = _emit_invalid(rng)
    # Enforce max length 64 as per stub
    if len(token) > 64:
        token = token[:64]
    # ASCII-encode
    return token.encode('ascii', errors='ignore')
